// Multiple classes in one file for the runnable demo.
package com.bank.rate;

import java.util.logging.*;

public class RateTierDemo {
    private static final Logger log = Logger.getLogger(RateTierDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Interest-rate tier thresholds (basis points), sorted ascending
        int[] tiers = {300, 500, 700, 900};

        RateTierService service = new RateTierService();

        log.info("Position for existing threshold 700");
        log.info("Index -> " + service.search(tiers, 700));   // found at 2

        log.info("Position to insert new threshold 600 (gap)");
        log.info("Index -> " + service.search(tiers, 600));   // insert at 2

        log.info("Position to insert threshold 100 (below all)");
        log.info("Index -> " + service.search(tiers, 100));   // insert at 0

        log.info("Position to insert threshold 1000 (above all)");
        log.info("Index -> " + service.search(tiers, 1000));  // insert at 4
    }
}

// ─── Would be in service/RateTierService.java ───
class RateTierService {
    // Return the index of target, or the insertion index if absent. O(log n).
    int search(int[] arr, int target) {
        int low = 0, high = arr.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;   // overflow-safe
            if (arr[mid] == target) {
                return mid;                     // found
            } else if (arr[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return low;  // low is the lower-bound insertion position
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
